.fs-team-card .elementor-flip-box::before { content: ""; position: absolute; inset: 0; border-radius: 30px; pointer-events: none;
  background: radial-gradient(260px 220px at 50% 300px, rgba(50, 153, 213, .9), transparent 70%), var(--fs-purple);
  box-shadow: 0 20px 40px -24px rgba(28, 22, 72, .55); transform: rotateY(0deg) translateZ(-1px);
